/bin/bash -lc 'for p in /AGENTS.md /home/AGENTS.md /home/leo-ribeiro/AGENTS.md /home/leo-ribeiro/codex-economy/AGENTS.md /home/leo-ribeiro/codex-economy/evidence/AGENTS.md /home/leo-ribeiro/codex-economy/evidence/confirmation-v2/AGENTS.md /home/leo-ribeiro/codex-economy/evidence/confirmation-v2/workspaces/AGENTS.md; do if [ -f "$p" ]; then cat "$p"; fi; done
python - <<'"'PY'
from pathlib import Path
import hashlib, json
root = Path.cwd()
for p in root.rglob('AGENTS.md'):
    if '.git' not in p.parts:
        print(f'{p}:\\n{p.read_text()}')
for name in ('logic.py', 'check.py'):
    print(f'{name}:\\n{Path(name).read_text()}')
snapshot = {str(p.relative_to(root)): hashlib.sha256(p.read_bytes()).hexdigest() for p in root.rglob('*') if p.is_file() and '.git' not in p.relative_to(root).parts}
Path('/tmp/python-distance-2-B-before.json').write_text(json.dumps(snapshot))
PY"

